    shard_id_set data_shards;
    for (raw_shard_id_t raw_shard = start;
         raw_shard < int(start) + count;
         ++raw_shard) {
      shard_id_t shard = chunk_mapping[int(raw_shard)];
      data_shards.insert(shard);
    }
    return data_shards;
  }

