59	ECBackend::_read(const hobject_t& hoid,
60	                 const uint64_t object_size,
61	                 const uint64_t off,
62	                 const uint64_t len,
63	                 const uint32_t flags)
64	{
65	  LOG_PREFIX(ECBackend::_read);
66	  const auto [aligned_off, aligned_len] =
67	    sinfo.for_default().ro_offset_len_to_stripe_ro_offset_len(off, len);
68	  std::map<hobject_t, std::list<ec_align_t>> reads;
69	  reads[hoid].emplace_back(
70	    ec_align_t{aligned_off, aligned_len, flags});
71	  seastar::promise<ceph::bufferlist> promise;
72	  auto ret = promise.get_future();
73	  objects_read_and_reconstruct(
74	    reads,
75	    fast_read,
76	    object_size,
77	    make_gen_lambda_context<ec_extents_t &&>(
78	      [hoid, off, len, promise=std::move(promise), FNAME,
79	       &dpp=this->dpp](auto&& results) mutable {
80	        ceph_assert(results.size() == 1);
81	        ceph_assert(results.count(hoid) == 1);
82	        auto& got = results.at(hoid);
83	        if (got.err < 0) {
84	          ceph_abort_msg("implement error handling");
85	          return;
86	        }
87		auto range = got.emap.get_containing_range(off, len);
88		ceph_assert(range.first != range.second);
89		ceph_assert(range.first.get_off() <= off);
90	        DEBUGDPP("hoid={} offset={}", dpp, hoid, off);
91	        DEBUGDPP("hoid={} range_offset={}", dpp, hoid, range.first.get_off());
92	        DEBUGDPP("hoid={} length={}", dpp, hoid, len);
93	        DEBUGDPP("hoid={} range_length={}", dpp, hoid, range.first.get_len());
94		ceph_assert(
95		  (off + len) <=
96		  (range.first.get_off() + range.first.get_len()));
97	        ceph::bufferlist clients_bl;
98		clients_bl.substr_of(
99		  range.first.get_val(),
100		  off - range.first.get_off(),
101		  len);
102	        promise.set_value(std::move(clients_bl));
103	      }));
104	  return ret;
105	}
