107	struct ECCrimsonOp : ECCommon::RMWPipeline::Op {
108	  PGTransactionUPtr t;
109	  const PGLog &pg_log;
110	
111	  static PGTransactionUPtr translate_transaction(
112	    ceph::os::Transaction&& t,
113	    crimson::osd::ObjectContextRef &&obc)
114	  {
115	    auto t_pg = std::make_unique<PGTransaction>();
116	    t_pg->add_obc(std::move(obc));
117	    auto i = std::begin(t);
118	    while (i.have_op()) {
119	      auto* op = i.decode_op();
120	      logger().debug("ECBackend::{} decoded op={} ghobj={} dest_ghobj={}",
121			     __func__,
122			     static_cast<uint32_t>(op->op),
123			     i.get_oid(op->oid),
124			     i.get_oid(op->dest_oid));
125	      switch (op->op) {
126	      case ceph::os::Transaction::OP_NOP:
127		// please notice PG::Transaction nop() takes hoid but
128		// the os::Transaction::nop() is parameterless.
129		continue;
130	      case ceph::os::Transaction::OP_CREATE:
131		t_pg->create(i.get_oid(op->oid).hobj);
132		break;
133	      case ceph::os::Transaction::OP_TOUCH:
134		t_pg->create(i.get_oid(op->oid).hobj);
135		break;
136	      case ceph::os::Transaction::OP_REMOVE:
137		t_pg->remove(i.get_oid(op->oid).hobj);
138		break;
139	      case ceph::os::Transaction::OP_SETATTR:
140		{
141		auto name = i.decode_string();
142		ceph::bufferlist bl;
143	        i.decode_bl(bl);
144		t_pg->setattr(i.get_oid(op->oid).hobj,
145			      name,
146			      bl);
147		}
148		break;
149	      case ceph::os::Transaction::OP_SETATTRS:
150		{
151		std::map<std::string, ceph::bufferlist, std::less<>> aset;
152	        i.decode_attrset(aset);
153		t_pg->setattrs(i.get_oid(op->oid).hobj, aset);
154		}
155		break;
156	      case ceph::os::Transaction::OP_RMATTR:
157		t_pg->rmattr(i.get_oid(op->oid).hobj, i.decode_string());
158		break;
159	      case ceph::os::Transaction::OP_RMATTRS:
160		ceph_abort_msg("Not present in PGTransaction");
161		break;
162	      case ceph::os::Transaction::OP_OMAP_CLEAR:
163		t_pg->omap_clear(i.get_oid(op->oid).hobj);
164		break;
165	      case ceph::os::Transaction::OP_OMAP_SETKEYS:
166		{
167		std::map<std::string, ceph::bufferlist> aset;
168		i.decode_attrset(aset);
169		t_pg->omap_setkeys(i.get_oid(op->oid).hobj, aset);
170		}
171		break;
172	      case ceph::os::Transaction::OP_OMAP_RMKEYS:
173		{
174		bufferlist keys_bl;
175	        i.decode_keyset_bl(&keys_bl);
176		t_pg->omap_rmkeys(i.get_oid(op->oid).hobj, keys_bl);
177		}
178		break;
179	      case ceph::os::Transaction::OP_OMAP_RMKEYRANGE:
180		{
181		std::string first = i.decode_string();
182		std::string last = i.decode_string();
183		t_pg->omap_rmkeyrange(i.get_oid(op->oid).hobj, first, last);
184		}
185		break;
186	      case ceph::os::Transaction::OP_OMAP_SETHEADER:
187		{
188		ceph::bufferlist bl;
189		i.decode_bl(bl);
190		t_pg->omap_setheader(i.get_oid(op->oid).hobj, bl);
191		}
192		break;
193	      case ceph::os::Transaction::OP_WRITE:
194		{
195		ceph::bufferlist bl;
196		i.decode_bl(bl);
197		t_pg->write(i.get_oid(op->oid).hobj,
198			    op->off,
199			    op->len,
200			    bl,
201			    i.get_fadvise_flags());
202		}
203		break;
204	      case ceph::os::Transaction::OP_ZERO:
205		t_pg->zero(i.get_oid(op->oid).hobj, op->off, op->len);
206		break;
207	      case ceph::os::Transaction::OP_TRUNCATE:
208		t_pg->truncate(i.get_oid(op->oid).hobj, op->off);
209		break;
210	      case ceph::os::Transaction::OP_SETALLOCHINT:
211		t_pg->set_alloc_hint(i.get_oid(op->oid).hobj,
212				     op->expected_object_size,
213				     op->expected_write_size,
214				     op->hint);
215	        break;
216	      case ceph::os::Transaction::OP_CLONERANGE2:
217		t_pg->clone_range(i.get_oid(op->oid).hobj,
218				  i.get_oid(op->dest_oid).hobj,
219				  op->off,
220				  op->len,
