{
  for (const auto &single_region: to_read) {
    sinfo.for_default().ro_range_to_shard_extent_set_with_parity(single_region.offset,
                                                   single_region.size,
                                                   want_shard_reads);
  }
  dout(20) << __func__ << ": to_read " << to_read
  << " read_request " << want_shard_reads << dendl;
}

