145	  const std::map<std::string, ceph::bufferlist, std::less<>>& raw_attrs,
146	  RecoveryOp &op)
147	{
148	  if (!op.obc) {
149	    // attrs only reference the origin bufferlist (decode from
150	    // ECSubReadReply message) whose size is much greater than attrs
151	    // in recovery. If obc cache it (get_obc maybe cache the attr),
152	    // this causes the whole origin bufferlist would not be free
153	    // until obc is evicted from obc cache. So rebuild the
154	    // bufferlist before cache it.
155	    for (map<string, bufferlist>::iterator it = op.xattrs.begin();
156	         it != op.xattrs.end();
157	         ++it) {
158	      it->second.rebuild();
159	    }
160	    // Need to remove ECUtil::get_hinfo_key() since it should not leak out
161	    // of the backend (see bug #12983)
162	    map<string, bufferlist, less<>> sanitized_attrs(op.xattrs);
163	    sanitized_attrs.erase(ECUtil::get_hinfo_key());
164	    op.obc = get_parent()->get_obc(op.hoid, sanitized_attrs);
165	    ceph_assert(op.obc);
166	    op.recovery_info.size = op.obc->obs.oi.size;
167	    op.recovery_info.oi = op.obc->obs.oi;
