139	uint64_t ScrubBackend::logical_to_ondisk_size(uint64_t logical_size,
140	                                 shard_id_t shard_id,
141	                                 bool hinfo_present,
142	                                 uint64_t expected_size) const
143	{
144	  uint64_t ondisk_size = m_pg.logical_to_ondisk_size(logical_size, shard_id, false);
145	
146	  if (!hinfo_present || ondisk_size == expected_size) {
147	    return ondisk_size;
148	  }
149	
150	  // This object does not match the expected size, but hinfo is present. In this
151	  // case there are valid reasons for the shard to be *either* size when using
152	  // optimised EC. The following function checks the expected size from legacy
153	  // EC.
154	  uint64_t legacy_ondisk_size = m_pg.logical_to_ondisk_size(logical_size, shard_id, true);
155	  if (expected_size == legacy_ondisk_size) {
156	    return legacy_ondisk_size;
157	  }
158	
159	  // If this return is reached, then the size is corrupt and what we return
160	  // here is relevant to the error message only.  Return the non-legacy value
161	  // as it might be more useful in debug.
162	  return ondisk_size;
163	}
