132	/// a collection of the basic scheduling information of a scrub target:
133	/// target time to scrub, and the 'not before'.
134	struct scrub_schedule_t {
135	  /**
136	   * the time at which we are allowed to start the scrub. Never
137	   * decreasing after 'scheduled_at' is set.
138	   */
139	  utime_t not_before{utime_t::max()};
140	
141	  /**
142	   * the 'scheduled_at' is the time at which we intended the scrub to be scheduled.
143	   * For periodic (regular) scrubs, it is set to the time of the last scrub
144	   * plus the scrub interval (plus some randomization). Priority scrubs
145	   * have their own specific rules for the target time. E.g.:
146	   * - for operator-initiated scrubs: 'target' is set to 'scrub_must_stamp';
147	   * - same for re-scrubbing (deep scrub after a shallow scrub that ended with
148	   *   errors;
149	   * - when requesting a scrub after a repair (the highest priority scrub):
150	   *   the target is set to '0' (beginning of time);
151	   */
152	  utime_t scheduled_at{utime_t::max()};
153	
154	  std::partial_ordering operator<=>(const scrub_schedule_t& rhs) const
155	  {
156	    // when compared - the 'not_before' is ignored, assuming
157	    // we never compare jobs with different eligibility status.
158	    return scheduled_at <=> rhs.scheduled_at;
159	  };
