142	                                 uint64_t expected_size,
143	                                 uint64_t chunk_size) const
144	{
145	  uint64_t ondisk_size = m_pg.logical_to_ondisk_size(logical_size, shard_id, false, chunk_size);
146	
147	  if (!hinfo_present || ondisk_size == expected_size) {
148	    return ondisk_size;
149	  }
150	
151	  // This object does not match the expected size, but hinfo is present. In this
152	  // case there are valid reasons for the shard to be *either* size when using
153	  // optimised EC. The following function checks the expected size from legacy
154	  // EC.
155	  uint64_t legacy_ondisk_size = m_pg.logical_to_ondisk_size(logical_size, shard_id, true, chunk_size);
156	  if (expected_size == legacy_ondisk_size) {
157	    return legacy_ondisk_size;
158	  }
159	
160	  // If this return is reached, then the size is corrupt and what we return
161	  // here is relevant to the error message only.  Return the non-legacy value
162	  // as it might be more useful in debug.
163	  return ondisk_size;
